/* v585: «حذف» بصفحة التصنيف — يسأل أول، وبعد الحذف يختفي من القائمة فوراً */
async function cpDelOne(pid){
  if(!(await delProduct(pid))) return;
  try{ if(myShopDoc && Array.isArray(myShopDoc.products)) myShopDoc.products=myShopDoc.products.filter(x=>_cpPid(x)!==pid) }catch(e){}
  _cpLinks=_cpLinks.filter(x=>x!==pid);
  cpPaintList();
}

  cmvPaint();
}
function cmvPaint(){
  const box=document.getElementById('cmvBody'); if(!box) return;
  const pid=_cmv.pid, P=v=>JSON.stringify(v).replace(/"/g,'&quot;');
  const here=new Set(myCats.filter(c=>(_catPids[c.id]||new Set()).has(pid)).map(c=>c.id));
  const nowEl=document.getElementById('cmvNow');
  if(nowEl){ const hs=myCats.filter(c=>here.has(c.id)).map(c=>{ const pr=c.parent_id&&myCats.find(x=>x.id===c.parent_id); return (pr?pr.name+' › ':'')+c.name });
    nowEl.innerHTML=hs.length?'هسه بـ: <b>'+hs.map(esc).join('، ')+'</b>':'هسه: <b>بلا تصنيف</b>' }
  const chip=(c,label)=>{ const at=here.has(c.id), ns=c.parent_id?0:_cSubs(myCats,c.id).length;
    const go=(!c.parent_id && ns && !label) ? `_cmv.view=${P(c.id)};cmvPaint()` : `cmvPick(${P(pid)},${P(c.id)})`;
    return `<button type="button" class="cmv-c${at?' at':''}" ${at?'disabled':''} onclick="${go}"><span>${esc(label||c.name)}</span>${at?'<em>هنا</em>':(!label&&ns?`<i>${ns} ›</i>`:'')}</button>` };
  let html='';
  const q=_normAr(_cmv.q||'');
  if(q){
    const hits=myCats.filter(c=>_normAr(c.name).includes(q));
    html='<div class="cmv-g">'+(hits.map(c=>{ const pr=c.parent_id&&myCats.find(x=>x.id===c.parent_id); return chip(c,(pr?pr.name+' › ':'')+c.name) }).join('')||'<div class="as-empty">ماكو قسم بهذا الاسم</div>')+'</div>';
  }else if(_cmv.view){
    const par=myCats.find(c=>c.id===_cmv.view);
    html=`<button type="button" class="cmv-back" onclick="_cmv.view='';cmvPaint()">‹ كل الأقسام</button><div class="cmv-h">${esc(par?par.name:'')}</div>`
      +'<div class="cmv-g">'+(par?chip(par,par.name+' (القسم نفسه)'):'')+_cSubs(myCats,_cmv.view).map(x=>chip(x)).join('')+'</div>';
  }else{
    /* قريب منه: القسم الرئيسي وفروعه للقسم اللي المادة بيه هسه */
    const base=myCats.find(c=>here.has(c.id)), top=base?(base.parent_id?myCats.find(c=>c.id===base.parent_id):base):null;
    const near=top?[top].concat(_cSubs(myCats,top.id)):[];
    if(near.length>1) html+='<div class="cmv-h">قريب منه</div><div class="cmv-g">'+near.map(c=>chip(c,c.id===top.id?c.name+' (الرئيسي)':c.name)).join('')+'</div>';
    html+='<div class="cmv-h">كل الأقسام</div><div class="cmv-g">'+_cTop(myCats).map(c=>chip(c)).join('')+'</div>';
  }
  const curId=(_cpCat&&!_cpCat.virtual)?_cpCat.id:null;
  if(curId && !q) html+=`<button type="button" class="cmv-rm" onclick="cmvPick(${P(pid)},'')">شيله من «${esc(_cpCat.name)}»</button>`;
  box.innerHTML=html;

/* v582: نفس شكل لوحة «الأقسام الفرعية» — عنوان + عدّاد + سطر شرح واحد، بلا إيموجي */
if(_brMine===null){ box.innerHTML='<section class="sts"><div class="sts-h"><b>البراندات</b></div><p class="sts-d">ما گدرنا نجيبها، جرّب بعد شوية.</p></section>'; return }
const X='<svg class="wic" viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M7 7l10 10M17 7 7 17"/></svg>';
const CAM='<svg class="wic" viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M4 8h3l2-2.5h6L17 8h3v11H4z"/><circle cx="12" cy="13" r="3.5"/></svg>';
box.innerHTML=`<section class="sts"><div class="sts-h"><b>البراندات</b><span class="sts-n">${_brMine.length} من 12</span></div>
  <p class="sts-d">تطلع للزبون بقسم «اكتشف البراندات». اكتب الاسم مثل ما مكتوب على المنتجات، واضغط الدائرة وحط شعاره.</p>
  ${_brMine.length?`<div class="brc-l">${_brMine.map(b=>{ const n=_brCount(b.q||b.name); return `<span class="brc${n?'':' z'}"><button type="button" class="brc-im${b.img?' on':''}" onclick="brImgPick('${b.id}')" aria-label="${b.img?'غيّر':'حط'} شعار ${esc(b.name)}">${b.img?`<img src="${esc(b.img)}" alt="">`:CAM}</button><b>${esc(b.name)}</b><i>${n?n+' منتج':'ما بيه منتجات'}</i><button type="button" onclick="brDel('${b.id}')" aria-label="شيل ${esc(b.name)}">${X}</button></span>` }).join('')}</div>`:''}
  ${_brMine.length<12?`<div class="brc-add"><input id="brNew" type="text" maxlength="40" placeholder="اسم البراند، مثلاً المراعي" oninput="brHint()" onkeydown="if(event.key==='Enter')brAdd()"><button type="button" onclick="brAdd()">أضف</button></div><div class="brm-h" id="brHint"></div>`:'<p class="sts-d">وصلت 12 براند. شيل واحد حتى تضيف غيره.</p>'}
</section>`;

/* v583: شعار البراند — يتحفظ مثل ما هو (بلا قص ولا شيل خلفية)، على أرضية بيضاء */
function brImgPick(id){
  let f=document.getElementById('brImgFile');
  if(!f){ f=document.createElement('input'); f.type='file'; f.accept='image/*'; f.id='brImgFile'; f.style.display='none'; f.onchange=()=>brImgUp(f); document.body.appendChild(f) }
  window._brImgId=id; f.value=''; f.click();
}
function _logoBlob(file){
  return new Promise((res,rej)=>{
    const u=URL.createObjectURL(file), im=new Image();
    im.onerror=()=>{ URL.revokeObjectURL(u); rej(new Error('صورة غير صالحة')) };
    im.onload=()=>{
      const S=400, pad=24, r=Math.min((S-pad*2)/im.width,(S-pad*2)/im.height), w=Math.round(im.width*r), h=Math.round(im.height*r);
      const c=document.createElement('canvas'); c.width=S; c.height=S; const x=c.getContext('2d');
      x.fillStyle='#fff'; x.fillRect(0,0,S,S); x.drawImage(im,(S-w)/2,(S-h)/2,w,h); URL.revokeObjectURL(u);
      c.toBlob(b=>b?res(b):rej(new Error('فشل الضغط')),'image/jpeg',0.9);
    };
    im.src=u;
  });
}
async function brImgUp(inp){
  const file=inp.files&&inp.files[0], id=window._brImgId; inp.value=''; if(!file||!id) return;
  try{
    toast('… جاري رفع الشعار');
    const url=await _upBlob(await _logoBlob(file),'brands');
    await rpc('shop_brand_set_img',{p_id:id, p_img:url});
    const b=(_brMine||[]).find(x=>x.id===id); if(b) b.img=url;
    renderMyBrands(); toast('انحفظ الشعار ✓');
  }catch(e){ toast('ما انحفظ: '+errMsg(e)) }
}

