  ${act<5?`<button type="button" class="bnr-add" onclick="sbmAddOpen()"><svg class="wic" viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="M12 5v14M5 12h14"/></svg><span>بنر جديد</span></button>`:''}
  </div>${act>=5?'<p class="sts-d">وصلت 5 بنرات. احذف واحد حتى تضيف غيره.</p>':''}
</section>`;

